__author__ = 'NIORLYS'
n = int(input())
q = list(map(int, input().split()))
temp = [None] * (2 * n + 1)
temp[n] = 1
index = start_index = n
d = {}
is_permutation = True
for i in range(n - 1):
	try:
		if temp[index + q[i]] is not None:
			is_permutation = False
			break
		else:
			temp[index + q[i]] = i + 2
			index += q[i]
			start_index = min(index, start_index)
	except IndexError:
		is_permutation = False
		break
if is_permutation:
	value = 1
	for i in range(start_index, start_index + n):
		if temp[i] is None:
			is_permutation = False
			break
		d[temp[i]] = value
		value += 1
if is_permutation:
	for key in range(n):
		print(d[key + 1], end=' ')
else:
	print(-1)
